  float Remaining_Capacity() const { return this->Remaining_Capacity_; }
  float& Remaining_Capacity() { return this->Remaining_Capacity_; }
  void Remaining_Capacity(float _val_) { this->Remaining_Capacity_ = _val_; }
  const std::string& Limit_Status() const { return this->Limit_Status_; }
